-- Ranh giới 6 tỉnh/thành ĐBSCL sau sáp nhập 2025, cùng dữ liệu với frontend/src/data/mekong-provinces.json
-- (MIT, vietnamese-provinces-database; tạo bằng frontend/scripts/build_map_layers.py).
-- Dùng để gán stations.province theo toạ độ: trạm nạp từ dữ liệu RYNAN không có tỉnh.
CREATE TABLE provinces (
    code VARCHAR(10)  PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE,
    geom geometry(MultiPolygon, 4326) NOT NULL
);

CREATE INDEX idx_provinces_geom ON provinces USING GIST (geom);

