-- Trạm nằm trong ranh giới; trạm ở cửa sông/ven biển có thể lệch ra ngoài ranh giới đã giản lược,
-- nên lấy tỉnh gần nhất trong vòng ~5 km
UPDATE stations s
SET province = (
    SELECT p.name FROM provinces p
    WHERE ST_DWithin(p.geom, s.location, 0.05)
    ORDER BY ST_Distance(p.geom, s.location)
    LIMIT 1
)
WHERE s.province IS NULL;
